import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { ChannelPage } from "./src/ChannelPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { getChannels, getChannel, getChannelMessages } from "./src/queries" with { type: "ref" };
import { createChannel, createMessage, markAsRead } from "./src/actions" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };
import { seedDevData } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "chat",
  title: "Real-Time Chat Application",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  db: {
    seeds: [seedDevData],
  },
  spec: [
    route("MainRoute", "/", page(MainPage, { authRequired: true })),
    route("ChannelRoute", "/channel/:id", page(ChannelPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getChannels, { entities: ["Channel"] }),
    query(getChannel, { entities: ["Channel"] }),
    query(getChannelMessages, { entities: ["Message", "ReadReceipt", "User"] }),
    action(createChannel, { entities: ["Channel"] }),
    action(createMessage, { entities: ["Message", "ReadReceipt"] }),
    action(markAsRead, { entities: ["ReadReceipt", "Message"] }),
  ],
});

import { Server, Socket } from "socket.io";
import type { WebSocketFn } from "wasp/server/webSocket";

let ioInstance: Server | null = null;

export const getIO = (): Server => {
  if (!ioInstance) {
    throw new Error("Socket.IO server instance is not initialized yet");
  }
  return ioInstance;
};

// Map of socketId -> Set of channelIds that the socket is currently in
const socketChannels = new Map<string, Set<number>>();

// Map of socketId -> username
const socketUsernames = new Map<string, string>();

const getActiveUsernamesInChannel = (io: Server, channelId: number): string[] => {
  const roomName = `channel-${channelId}`;
  const room = io.sockets.adapter.rooms.get(roomName);
  if (!room) return [];
  const usernames = new Set<string>();
  for (const socketId of room) {
    const uname = socketUsernames.get(socketId);
    if (uname) {
      usernames.add(uname);
    }
  }
  return Array.from(usernames);
};

export const webSocketFn: WebSocketFn = (io, context) => {
  ioInstance = io;

  io.on("connection", (socket: Socket) => {
    const user = socket.data.user;
    if (!user) {
      console.log("No authenticated user on socket connection");
      return;
    }

    const username = user.username;
    socketUsernames.set(socket.id, username);

    socket.on("joinChannel", ({ channelId }: { channelId: number }) => {
      const roomName = `channel-${channelId}`;
      socket.join(roomName);

      if (!socketChannels.has(socket.id)) {
        socketChannels.set(socket.id, new Set());
      }
      socketChannels.get(socket.id)!.add(channelId);

      const activeUsers = getActiveUsernamesInChannel(io, channelId);
      io.to(roomName).emit("activeUsers", activeUsers);
    });

    socket.on("leaveChannel", ({ channelId }: { channelId: number }) => {
      const roomName = `channel-${channelId}`;
      socket.leave(roomName);

      socketChannels.get(socket.id)?.delete(channelId);

      const activeUsers = getActiveUsernamesInChannel(io, channelId);
      io.to(roomName).emit("activeUsers", activeUsers);
    });

    socket.on("typing", ({ channelId, isTyping }: { channelId: number, isTyping: boolean }) => {
      const roomName = `channel-${channelId}`;
      socket.to(roomName).emit("typing", { username, isTyping });
    });

    socket.on("disconnect", () => {
      const channelsJoined = socketChannels.get(socket.id);
      if (channelsJoined) {
        for (const channelId of channelsJoined) {
          const roomName = `channel-${channelId}`;
          // Wait, the socket is already removed from the room, so getActiveUsernamesInChannel
          // will calculate the list excluding this socket.
          // But wait, getActiveUsernamesInChannel uses socketUsernames.get(socketId).
          // We must delete from socketUsernames AFTER calculating/emitting activeUsers,
          // or we can remove it from room manually if it's still there, but since it's disconnected,
          // it's not in the room anymore.
        }
      }

      // First, calculate active users for each channel BEFORE cleaning up maps
      const updates: { roomName: string; activeUsers: string[] }[] = [];
      if (channelsJoined) {
        for (const channelId of channelsJoined) {
          const roomName = `channel-${channelId}`;
          // Temporarily remove this socketId from room if it's somehow still in room's Set
          const room = io.sockets.adapter.rooms.get(roomName);
          if (room) {
            room.delete(socket.id);
          }
          // Also remove from socketUsernames temporarily to calculate correct active users
          socketUsernames.delete(socket.id);
          const activeUsers = getActiveUsernamesInChannel(io, channelId);
          updates.push({ roomName, activeUsers });
          // Restore socketUsernames for other iterations if needed (though socket is disconnecting anyway)
          socketUsernames.set(socket.id, username);
        }
      }

      // Cleanup
      socketChannels.delete(socket.id);
      socketUsernames.delete(socket.id);

      // Emit the updates
      for (const update of updates) {
        io.to(update.roomName).emit("activeUsers", update.activeUsers);
      }
    });
  });
};

import { HttpError } from "wasp/server";

export const getChannels = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Channel.findMany({
    orderBy: { name: "asc" },
  });
};

export const getChannel = async ({ id }: { id: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const channel = await context.entities.Channel.findUnique({
    where: { id },
  });
  if (!channel) {
    throw new HttpError(404, "Channel not found");
  }
  return channel;
};

export const getChannelMessages = async ({ channelId }: { channelId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const messages = await context.entities.Message.findMany({
    where: { channelId },
    orderBy: { createdAt: "asc" },
    include: {
      sender: true,
    },
  });

  const readReceipts = await context.entities.ReadReceipt.findMany({
    where: { channelId },
    include: {
      user: true,
    },
  });

  return messages.map((msg: any) => {
    const readers = readReceipts
      .filter((rr: any) => rr.userId !== msg.senderId && rr.lastReadMessageId >= msg.id)
      .map((rr: any) => ({
        username: rr.user.username,
        userId: rr.userId,
      }));
    return {
      ...msg,
      readers,
    };
  });
};

import { HttpError } from "wasp/server";
import { getIO } from "./webSocket";

export const createChannel = async ({ name }: { name: string }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const trimmedName = name.trim();
  if (!trimmedName) {
    throw new HttpError(400, "Channel name cannot be empty");
  }

  const existingChannel = await context.entities.Channel.findUnique({
    where: { name: trimmedName },
  });

  if (existingChannel) {
    throw new HttpError(400, "A channel with this name already exists");
  }

  return context.entities.Channel.create({
    data: { name: trimmedName },
  });
};

export const createMessage = async (
  { channelId, content }: { channelId: number; content: string },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const trimmedContent = content.trim();
  if (!trimmedContent) {
    throw new HttpError(400, "Message content cannot be empty");
  }

  const message = await context.entities.Message.create({
    data: {
      content: trimmedContent,
      channelId,
      senderId: context.user.id,
    },
    include: {
      sender: true,
    },
  });

  await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    update: {
      lastReadMessageId: message.id,
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId: message.id,
    },
  });

  try {
    const io = getIO();
    io.to(`channel-${channelId}`).emit("messageCreated", {
      ...message,
      readers: [],
    });
  } catch (err) {
    console.error("Failed to broadcast messageCreated event:", err);
  }

  return message;
};

export const markAsRead = async (
  { channelId, lastReadMessageId }: { channelId: number; lastReadMessageId: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const receipt = await context.entities.ReadReceipt.upsert({
    where: {
      userId_channelId: {
        userId: context.user.id,
        channelId,
      },
    },
    update: {
      lastReadMessageId,
    },
    create: {
      userId: context.user.id,
      channelId,
      lastReadMessageId,
    },
  });

  try {
    const io = getIO();
    io.to(`channel-${channelId}`).emit("readReceiptUpdated", {
      userId: context.user.id,
      username: context.user.username,
      lastReadMessageId,
    });
  } catch (err) {
    console.error("Failed to broadcast readReceiptUpdated event:", err);
  }

  return receipt;
};

