import { useState } from "react";
import { Link } from "react-router-dom";
import { useQuery, getChannels, createChannel } from "wasp/client/operations";
import { logout } from "wasp/client/auth";

export function MainPage({ user }: { user: any }) {
  const { data: channels, isLoading, error } = useQuery(getChannels);
  const [newChannelName, setNewChannelName] = useState("");
  const [createError, setCreateError] = useState("");

  const handleCreateChannel = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreateError("");
    const trimmed = newChannelName.trim();
    if (!trimmed) {
      setCreateError("Channel name cannot be empty");
      return;
    }
    try {
      await createChannel({ name: trimmed });
      setNewChannelName("");
    } catch (err: any) {
      setCreateError(err.message || "Failed to create channel");
    }
  };

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
        <h1 data-testid="main-title">Real-Time Chat</h1>
        <div>
          <span style={{ marginRight: "10px" }}>Hello, <strong>{user?.username}</strong>!</span>
          <button data-testid="logout-btn" onClick={logout} style={{ padding: "5px 10px" }}>Logout</button>
        </div>
      </header>

      <section style={{ marginBottom: "30px", padding: "15px", border: "1px solid #eee", borderRadius: "8px" }}>
        <h3>Create a New Channel</h3>
        <form onSubmit={handleCreateChannel} style={{ display: "flex", gap: "10px" }}>
          <input
            id="channel-name-input"
            data-testid="channel-name-input"
            type="text"
            value={newChannelName}
            onChange={(e) => setNewChannelName(e.target.value)}
            placeholder="e.g. #general"
            style={{ flex: 1, padding: "8px" }}
          />
          <button
            id="create-channel-btn"
            data-testid="create-channel-btn"
            type="submit"
            style={{ padding: "8px 15px" }}
          >
            Create Channel
          </button>
        </form>
        {createError && <p style={{ color: "red", marginTop: "5px" }}>{createError}</p>}
      </section>

      <section>
        <h3>Channels</h3>
        {isLoading && <p>Loading channels...</p>}
        {error && <p style={{ color: "red" }}>Error loading channels: {error.message}</p>}
        {channels && (
          <div data-testid="channels-list" style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {channels.length === 0 ? (
              <p>No channels available. Create one above!</p>
            ) : (
              channels.map((channel: any) => (
                <Link
                  key={channel.id}
                  data-testid="channel-link"
                  data-channel-id={channel.id}
                  to={`/channel/${channel.id}`}
                  style={{
                    padding: "10px",
                    border: "1px solid #ddd",
                    borderRadius: "4px",
                    textDecoration: "none",
                    color: "#333",
                    backgroundColor: "#f9f9f9"
                  }}
                >
                  {channel.name}
                </Link>
              ))
            )}
          </div>
        )}
      </section>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import { useQuery, getChannel, getChannelMessages, createMessage, markAsRead } from "wasp/client/operations";
import { useSocket, useSocketListener } from "wasp/client/webSocket";

export function ChannelPage({ user }: { user: any }) {
  const { id } = useParams<{ id: string }>();
  const channelId = parseInt(id || "", 10);

  const { data: channel, isLoading: isChannelLoading, error: channelError } = useQuery(getChannel, { id: channelId });
  const { data: initialMessages } = useQuery(getChannelMessages, { channelId });

  const [messages, setMessages] = useState<any[]>([]);
  const [activeUsers, setActiveUsers] = useState<string[]>([]);
  const [typingUsers, setTypingUsers] = useState<Record<string, boolean>>({});

  const [messageContent, setMessageContent] = useState("");
  const [isLocalTyping, setIsLocalTyping] = useState(false);
  const [typingTimeoutId, setTypingTimeoutId] = useState<NodeJS.Timeout | null>(null);

  const { socket, isConnected } = useSocket();

  // Sync initial messages from query
  useEffect(() => {
    if (initialMessages) {
      setMessages(initialMessages);
    }
  }, [initialMessages]);

  // Join and leave channel room via WebSocket
  useEffect(() => {
    if (socket && isConnected && !isNaN(channelId)) {
      socket.emit("joinChannel", { channelId });
      return () => {
        socket.emit("leaveChannel", { channelId });
      };
    }
  }, [socket, isConnected, channelId]);

  // Mark the channel as read when messages load or change
  useEffect(() => {
    if (messages.length > 0 && !isNaN(channelId)) {
      const lastMessage = messages[messages.length - 1];
      markAsRead({ channelId, lastReadMessageId: lastMessage.id }).catch((err) => {
        console.error("Failed to mark as read:", err);
      });
    }
  }, [messages.length, channelId]);

  // Cleanup typing timeout on unmount
  useEffect(() => {
    return () => {
      if (typingTimeoutId) {
        clearTimeout(typingTimeoutId);
      }
    };
  }, [typingTimeoutId]);

  // Listen to WebSocket events
  useSocketListener("activeUsers", (users: string[]) => {
    setActiveUsers(users);
  });

  useSocketListener("typing", ({ username, isTyping }: { username: string; isTyping: boolean }) => {
    setTypingUsers((prev) => ({
      ...prev,
      [username]: isTyping,
    }));
  });

  useSocketListener("messageCreated", (newMessage: any) => {
    if (newMessage.channelId === channelId) {
      setMessages((prev) => {
        if (prev.some((m) => m.id === newMessage.id)) return prev;
        return [...prev, newMessage];
      });

      // If we are currently viewing the channel and the message is from someone else, mark it as read
      if (newMessage.senderId !== user.id) {
        markAsRead({ channelId, lastReadMessageId: newMessage.id }).catch((err) => {
          console.error("Failed to mark as read on new message:", err);
        });
      }
    }
  });

  useSocketListener(
    "readReceiptUpdated",
    ({ userId, username, lastReadMessageId }: { userId: number; username: string; lastReadMessageId: number }) => {
      setMessages((prev) =>
        prev.map((msg) => {
          if (userId !== msg.senderId && lastReadMessageId >= msg.id) {
            const alreadyReader = msg.readers.some((r: any) => r.userId === userId);
            if (!alreadyReader) {
              return {
                ...msg,
                readers: [...msg.readers, { userId, username }],
              };
            }
          } else if (userId !== msg.senderId && lastReadMessageId < msg.id) {
            return {
              ...msg,
              readers: msg.readers.filter((r: any) => r.userId !== userId),
            };
          }
          return msg;
        })
      );
    }
  );

  const handleKeyDown = () => {
    if (!socket || !isConnected) return;

    if (!isLocalTyping) {
      setIsLocalTyping(true);
      socket.emit("typing", { channelId, isTyping: true });
    }

    if (typingTimeoutId) {
      clearTimeout(typingTimeoutId);
    }

    const timeoutId = setTimeout(() => {
      setIsLocalTyping(false);
      socket.emit("typing", { channelId, isTyping: false });
    }, 3000);

    setTypingTimeoutId(timeoutId);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = messageContent.trim();
    if (!trimmed) return;

    // Clear typing state immediately
    if (typingTimeoutId) {
      clearTimeout(typingTimeoutId);
      setTypingTimeoutId(null);
    }
    if (isLocalTyping) {
      setIsLocalTyping(false);
      socket?.emit("typing", { channelId, isTyping: false });
    }

    setMessageContent("");

    try {
      await createMessage({ channelId, content: trimmed });
    } catch (err) {
      console.error("Failed to send message:", err);
    }
  };

  if (isNaN(channelId)) {
    return (
      <div style={{ padding: "20px" }}>
        <p>Invalid channel ID.</p>
        <Link data-testid="back-to-channels" to="/">Back to Channels</Link>
      </div>
    );
  }

  if (isChannelLoading) {
    return <div style={{ padding: "20px" }}>Loading channel...</div>;
  }

  if (channelError || !channel) {
    return (
      <div style={{ padding: "20px" }}>
        <p style={{ color: "red" }}>Error: {channelError?.message || "Channel not found"}</p>
