            &larr; Back
          </Link>
          <h1 data-testid="channel-title" style={{ display: "inline-block", margin: 0 }}>
            {channel.name}
          </h1>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: "0.9em", color: "#666" }}>
            Active users:
          </div>
          <div data-testid="active-users-list" style={{ display: "flex", gap: "5px", flexWrap: "wrap", justifyContent: "flex-end" }}>
            {activeUsers.map((uname) => (
              <span
                key={uname}
                data-testid="active-user-item"
                data-username={uname}
                style={{
                  fontSize: "0.8em",
                  backgroundColor: "#e1f5fe",
                  color: "#0288d1",
                  padding: "2px 6px",
                  borderRadius: "4px"
                }}
              >
                {uname}
              </span>
            ))}
          </div>
        </div>
      </header>

      <main style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "space-between", minHeight: 0 }}>
        {/* Messages List */}
        <div
          data-testid="messages-list"
          style={{
            flex: 1,
            overflowY: "auto",
            border: "1px solid #eee",
            borderRadius: "8px",
            padding: "15px",
            marginBottom: "15px",
            backgroundColor: "#fafafa"
          }}
        >
          {messages.length === 0 ? (
            <p style={{ color: "#999", textAlign: "center", marginTop: "40px" }}>No messages yet. Say hello!</p>
          ) : (
            messages.map((msg) => (
              <div
                key={msg.id}
                data-testid="message-item"
                data-message-id={msg.id}
                style={{
                  marginBottom: "15px",
                  padding: "10px",
                  backgroundColor: "#fff",
                  borderRadius: "6px",
                  boxShadow: "0 1px 2px rgba(0,0,0,0.05)"
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "4px" }}>
                  <span data-testid="message-sender" style={{ fontWeight: "bold" }}>
                    {msg.sender.username}
                  </span>
                  <span style={{ fontSize: "0.8em", color: "#999" }}>
                    {new Date(msg.createdAt).toLocaleTimeString()}
                  </span>
                </div>
                <div data-testid="message-content" style={{ wordBreak: "break-word", whiteSpace: "pre-wrap" }}>
                  {msg.content}
                </div>

                {/* Read Receipts Container */}
                <div
                  data-testid="message-read-receipts"
                  style={{
                    display: "flex",
                    gap: "4px",
                    flexWrap: "wrap",
                    marginTop: "6px",
                    fontSize: "0.75em",
                    color: "#888",
                    alignItems: "center"
                  }}
                >
                  {msg.readers && msg.readers.length > 0 && (
                    <>
                      <span style={{ marginRight: "2px" }}>✓ Read by:</span>
                      {msg.readers.map((reader: any) => (
                        <span
                          key={reader.userId}
                          data-testid="reader-name"
                          data-username={reader.username}
                          style={{
                            backgroundColor: "#f1f1f1",
                            padding: "1px 4px",
                            borderRadius: "3px"
                          }}
                        >
                          {reader.username}
                        </span>
                      ))}
                    </>
                  )}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer with Typing Indicators & Input Form */}
        <div>
          {/* Typing Indicators */}
          <div data-testid="typing-indicators" style={{ minHeight: "24px", marginBottom: "5px", fontSize: "0.85em", color: "#666" }}>
            {otherTypingUsers.map(([uname]) => (
              <span
                key={uname}
                data-testid="typing-user-item"
                data-username={uname}
                style={{ fontStyle: "italic", marginRight: "10px" }}
              >
                {uname} is typing...
