import { Outlet } from "react-router";
import "./App.css";

export function App() {
  return (
    <main className="flex min-h-screen w-full flex-col bg-neutral-50 text-neutral-800">
      <Outlet />
    </main>
  );
}

import { Server, Socket } from "socket.io";

let ioInstance: Server | null = null;

export const getIO = (): Server => {
  if (!ioInstance) {
    throw new Error("Socket.IO server instance is not initialized yet");
  }
  return ioInstance;
};

// Map of socketId -> Set of channelIds that the socket is currently in
const socketChannels = new Map<string, Set<number>>();

// Map of socketId -> username
const socketUsernames = new Map<string, string>();

const getActiveUsernamesInChannel = (io: Server, channelId: number): string[] => {
  const roomName = `channel-${channelId}`;
  const room = io.sockets.adapter.rooms.get(roomName);
  if (!room) return [];
  const usernames = new Set<string>();
  for (const socketId of room) {
    const uname = socketUsernames.get(socketId);
    if (uname) {
      usernames.add(uname);
    }
  }
  return Array.from(usernames);
};

export const webSocketFn = (io: Server, context: any) => {
  ioInstance = io;

  io.on("connection", (socket: Socket) => {
    const user = socket.data.user;
    if (!user) {
      console.log("No authenticated user on socket connection");
      return;
    }

    const username = user.username;
    socketUsernames.set(socket.id, username);

    socket.on("joinChannel", ({ channelId }: { channelId: number }) => {
      const roomName = `channel-${channelId}`;
      socket.join(roomName);

      if (!socketChannels.has(socket.id)) {
        socketChannels.set(socket.id, new Set());
      }
      socketChannels.get(socket.id)!.add(channelId);

      const activeUsers = getActiveUsernamesInChannel(io, channelId);
      io.to(roomName).emit("activeUsers", activeUsers);
    });

    socket.on("leaveChannel", ({ channelId }: { channelId: number }) => {
      const roomName = `channel-${channelId}`;
      socket.leave(roomName);

      socketChannels.get(socket.id)?.delete(channelId);

      const activeUsers = getActiveUsernamesInChannel(io, channelId);
      io.to(roomName).emit("activeUsers", activeUsers);
    });

    socket.on("typing", ({ channelId, isTyping }: { channelId: number, isTyping: boolean }) => {
      const roomName = `channel-${channelId}`;
      socket.to(roomName).emit("typing", { username, isTyping });
    });

    socket.on("disconnect", () => {
      const channelsJoined = socketChannels.get(socket.id);

      // First, calculate active users for each channel BEFORE cleaning up maps
      const updates: { roomName: string; activeUsers: string[] }[] = [];
      if (channelsJoined) {
        for (const channelId of channelsJoined) {
          const roomName = `channel-${channelId}`;
          // Temporarily remove this socketId from room if it's somehow still in room's Set
          const room = io.sockets.adapter.rooms.get(roomName);
          if (room) {
            room.delete(socket.id);
          }
          // Also remove from socketUsernames temporarily to calculate correct active users
          socketUsernames.delete(socket.id);
          const activeUsers = getActiveUsernamesInChannel(io, channelId);
          updates.push({ roomName, activeUsers });
          // Restore socketUsernames for other iterations if needed (though socket is disconnecting anyway)
          socketUsernames.set(socket.id, username);
        }
      }

      // Cleanup
      socketChannels.delete(socket.id);
      socketUsernames.delete(socket.id);

      // Emit the updates
      for (const update of updates) {
        io.to(update.roomName).emit("activeUsers", update.activeUsers);
      }
    });
  });
};
